"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["58875"],{34257(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.agregado_sem_fato_de_membro","status":422,"titulo":"O fato de membro do agregado n\xe3o pertence ao cat\xe1logo"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.agregado_sem_fato_de_membro","requisitos":["UNI-REQ-0143","UNI-REQ-0146"],"oQueAconteceu":["O administrador cadastrou um fato que resume respostas de grupo (`POST /api/configuracao/admin/fatos-candidato/agregados`) com um `fatoDeMembro` que n\xe3o \xe9 o c\xf3digo de nenhum fato do cat\xe1logo. Esse fato re\xfane as respostas dos membros de um grupo repet\xedvel, como a composi\xe7\xe3o familiar, a outro fato, e esse fato precisa existir (UNI-REQ-0146). O c\xf3digo \xe9 comparado como recebido, e mai\xfasculas e min\xfasculas contam: `renda_membro` n\xe3o \xe9 o fato `RENDA_MEMBRO`. Um `fatoDeMembro` em branco cai aqui.","A recusa vem na lista `errors` da resposta, com `field` igual a `fatoDeMembro`. Sem o fato de membro, o tipo de dado, a fonte dos valores e o v\xednculo do resumo de grupo, que saem dele, n\xe3o s\xe3o conferidos; as demais confer\xeancias do cadastro (c\xf3digo, nome, prote\xe7\xe3o de dados) seguem e aparecem na mesma resposta. Nada \xe9 gravado."],"comoResolver":["Informe o c\xf3digo de um fato que j\xe1 existe, listado no cat\xe1logo (`GET /api/configuracao/admin/fatos-candidato`). Ele precisa ser um fato declarado de membro de grupo, de tipo booleano ou categ\xf3rico, e estar ativo. Se o fato de membro ainda n\xe3o foi cadastrado, cadastre-o antes (`POST /api/configuracao/admin/fatos-candidato`), com escopo `MEMBRO_GRUPO`, e s\xf3 ent\xe3o o resumo de grupo."],"ondeAparece":["Cadastro de um fato do cat\xe1logo que resume respostas de grupo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);